class Account {
    public void processMonthlyMaintenance() {
        System.out.println("Deducting standard maintenance fee: $5.00");
    }
}

class StudentAccount extends Account {
    @Override
    public void processMonthlyMaintenance() {
        System.out.println("Student Account: Maintenance fee waived ($0.00)");
    }
}

class EnterpriseAccount extends Account {
    @Override
    public void processMonthlyMaintenance() {
        System.out.println("Enterprise Account: Maintenance fee $50.00 with dedicated support");
    }
}

public class GenericProcessorDemo {
    // Method accepts the generic parent type
    public static void runAudit(Account acc) {
        acc.processMonthlyMaintenance(); // Polymorphic dispatch!
    }

    public static void main(String[] args) {
        runAudit(new StudentAccount());
        runAudit(new EnterpriseAccount());
    }
}

