class ReportExporter {
    public void exportData(String data) {
        System.out.println("Exporting generic data: " + data);
    }
}

class CsvExporter extends ReportExporter {
    @Override
    public void exportData(String data) {
        System.out.println("CSV Export: " + data);
    }
}

class JsonExporter extends ReportExporter {
    @Override
    public void exportData(String data) {
        System.out.println("JSON Export: {\"report\": \"" + data + "\"}");
    }
}

class XmlExporter extends ReportExporter {
    @Override
    public void exportData(String data) {
        System.out.println("XML Export: <report>" + data + "</report>");
    }
}

class ReportService {
    public void publishReport(ReportExporter exporter, String data) {
        exporter.exportData(data);
    }
}

public class Main {
    public static void main(String[] args) {
        ReportService service = new ReportService();
        service.publishReport(new CsvExporter(), "id,name,data");
        service.publishReport(new JsonExporter(), "Q3_Financials");
        service.publishReport(new XmlExporter(), "Q3_Financials");
    }
}
